/// Write a dictionary-encoded column chunk with Optional(T) values (unified API).
/// Uses RLE_DICTIONARY encoding for efficient storage of low-cardinality columns.
/// is_optional: true if column is optional in schema (writes def levels), false for required columns.
pub fn writeColumnChunkDictOptionalWithPathArray(
    comptime T: type,
    allocator: std.mem.Allocator,
    output: *std.Io.Writer,
    path_in_schema: []const []const u8,
    values: []const Optional(T),
    is_optional: bool,
    start_offset: i64,
    codec: format.CompressionCodec,
    dictionary_size_limit: ?usize,
    dictionary_cardinality_threshold: ?f32,
    max_page_size: ?usize,
    write_page_checksum: bool,
) ColumnWriteError!ColumnChunkResult {
    if (values.len == 0) {
        // Fall back to plain encoding for empty columns
        return writeColumnChunkOptionalWithPathArray(T, allocator, output, path_in_schema, values, is_optional, start_offset, codec, write_page_checksum);
    }

    // Build dictionary from non-null values
    var unique_map = std.HashMap(T, u32, DictHashContext(T), std.hash_map.default_max_load_percentage).init(allocator);
    defer unique_map.deinit();
    var dict_values: std.ArrayListUnmanaged(T) = .empty;
    defer dict_values.deinit(allocator);

    var non_null_count: usize = 0;
    for (values) |v| {
        if (v != .null_value) non_null_count += 1;
    }

    var indices = allocator.alloc(u32, non_null_count) catch return error.OutOfMemory;
    defer allocator.free(indices);

    var idx: usize = 0;
    for (values) |v| {
        if (v != .null_value) {
            const gop = unique_map.getOrPut(v.value) catch return error.OutOfMemory;
            if (!gop.found_existing) {
                gop.value_ptr.* = try safe.castTo(u32, dict_values.items.len);
                dict_values.append(allocator, v.value) catch return error.OutOfMemory;
                // The dictionary only grows, so its first excess is the same decision
                // the old post-loop check made: fall back now instead of hashing on.

                // Byte arrays: copy raw bytes (no length prefix in statistics)
                return try allocator.dupe(u8, value);
            } else {
                @compileError("Unsupported type for statistics: " ++ @typeName(T));
            }
        }
    };
}

/// Statistics builder for byte array columns (variable length).
/// Uses lexicographic comparison for min/max.
pub const ByteArrayStatisticsBuilder = struct {
    min: ?[]u8 = null,
    max: ?[]u8 = null,
    null_count: i64 = 0,
    has_values: bool = false,
    allocator: std.mem.Allocator,

    const Self = @This();

    pub fn init(allocator: std.mem.Allocator) Self {
        return .{ .allocator = allocator };
    }

    pub fn deinit(self: *Self) void {
        if (self.min) |m| self.allocator.free(m);
        if (self.max) |m| self.allocator.free(m);
    }

    /// Update statistics with a slice of byte array values.
    pub fn update(self: *Self, values: []const []const u8) !void {
        if (values.len == 0) return;
        var lo = values[0];
        var hi = values[0];
        for (values[1..]) |v| {
            if (std.mem.order(u8, v, lo) == .lt) lo = v;
            if (std.mem.order(u8, v, hi) == .gt) hi = v;
        }
        // At most two owned copies per call instead of one per new extreme.
        try self.updateValue(lo);
        try self.updateValue(hi);
    }

    /// Update statistics with a single byte array value.
    fn updateValue(self: *Self, value: []const u8) !void {
        if (!self.has_values) {
            self.min = try self.allocator.dupe(u8, value);
            errdefer {
                self.allocator.free(self.min.?);
                self.min = null;
            }
            self.max = try self.allocator.dupe(u8, value);
            self.has_values = true;
        } else {
            if (std.mem.order(u8, value, self.min.?) == .lt) {
                self.allocator.free(self.min.?);
                self.min = null;
                self.min = try self.allocator.dupe(u8, value);
            }
            if (std.mem.order(u8, value, self.max.?) == .gt) {
                self.allocator.free(self.max.?);
                self.max = null;
                self.max = try self.allocator.dupe(u8, value);
            }
        }
    }

    /// Update statistics with a slice of nullable byte array values.
    /// Deprecated: Use updateOptional with Optional([]const u8) instead.
    fn updateNullable(self: *Self, values: []const ?[]const u8) !void {
        for (values) |v| {
            if (v) |val| {
                try self.updateValue(val);
            } else {
                self.null_count += 1;
            }
        }
    }

    /// Update statistics with a slice of Optional byte array values (unified API).
    /// This is the preferred method - accepts the same Optional type that Reader returns.
    pub fn updateOptional(self: *Self, values: []const Optional([]const u8)) !void {
        var lo: ?[]const u8 = null;
        var hi: ?[]const u8 = null;
        for (values) |v| switch (v) {
            .null_value => self.null_count += 1,
            .value => |val| {
                if (lo == null or std.mem.order(u8, val, lo.?) == .lt) lo = val;
                if (hi == null or std.mem.order(u8, val, hi.?) == .gt) hi = val;
            },
        };
        // At most two owned copies per call instead of one per new extreme.
        if (lo) |l| try self.updateValue(l);
        if (hi) |h| try self.updateValue(h);
    }

    /// Add to null count.
    pub fn addNulls(self: *Self, count: i64) void {
        self.null_count += count;
    }

    /// Build the Statistics struct.
    /// Ownership of min/max bytes is transferred to the returned Statistics.
    pub fn build(self: *Self) ?format.Statistics {
        if (!self.has_values) {
            if (self.null_count > 0) {
